/**
 * HTTP caching for public GET endpoints (CDN/browser). ETag is generated by Express.
 * @param {number} maxAge browser seconds
 * @param {number} [sMaxAge] shared-cache (CDN) seconds
 */
export const publicCache =
  (maxAge = 60, sMaxAge = 300) =>
  (_req, res, next) => {
    res.set(
      'Cache-Control',
      `public, max-age=${maxAge}, s-maxage=${sMaxAge}, stale-while-revalidate=${sMaxAge * 2}`,
    );
    next();
  };
